/* TalkAbout Sessions — service worker.
 *
 * Hand-written rather than generated by a build plugin. The caching rules here
 * are three cases long, and a plugin would add a Turbopack-compatibility risk
 * for no benefit at this size.
 *
 * What offline actually buys you: every briefing and debrief you have generated
 * already lives in localStorage, so caching the shell means the app opens in a
 * hall with no signal and you can read all of it. You simply cannot generate
 * anything new — which the UI already reports honestly.
 */

const VERSION = "v1";
const SHELL = `talkabout-shell-${VERSION}`;
const ASSETS = `talkabout-assets-${VERSION}`;

// Only the entry document. Next fingerprints everything else, so those are
// picked up at runtime instead of being listed here and going stale.
const SHELL_URLS = ["/"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL)
      .then((cache) => cache.addAll(SHELL_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== SHELL && key !== ASSETS)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

/** Content-hashed output and icons — safe to serve from cache indefinitely. */
function isStaticAsset(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    /\.(png|svg|webmanifest|woff2?)$/.test(url.pathname)
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Never cache generation or extraction. A stale AI answer replayed from cache
  // would be precisely the kind of quiet dishonesty this app exists to argue
  // against, and neither route can work offline anyway.
  if (url.pathname.startsWith("/api/")) return;

  // Navigations: prefer the network so a deploy is picked up immediately, and
  // fall back to the cached shell when there is no signal.
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(SHELL).then((cache) => cache.put("/", copy));
          return response;
        })
        .catch(() => caches.match("/", { ignoreSearch: true })),
    );
    return;
  }

  if (isStaticAsset(url)) {
    event.respondWith(
      caches.match(request).then(
        (hit) =>
          hit ??
          fetch(request).then((response) => {
            if (response.ok) {
              const copy = response.clone();
              caches.open(ASSETS).then((cache) => cache.put(request, copy));
            }
            return response;
          }),
      ),
    );
  }
});

self.addEventListener("message", (event) => {
  // Lets a newly installed worker take over without closing every tab.
  if (event.data === "SKIP_WAITING") {
    self.skipWaiting();
    return;
  }

  // The page reports what it loaded before this worker was controlling it, so
  // the first visit is enough to make the app work offline afterwards.
  if (event.data?.type === "WARM_CACHE" && Array.isArray(event.data.urls)) {
    event.waitUntil(
      caches.open(ASSETS).then(async (cache) => {
        const missing = [];
        for (const url of event.data.urls) {
          if (!(await cache.match(url))) missing.push(url);
        }
        // Individually, so one 404 cannot fail the whole batch the way
        // cache.addAll() would.
        await Promise.all(
          missing.map((url) =>
            fetch(url)
              .then((response) => (response.ok ? cache.put(url, response) : null))
              .catch(() => null),
          ),
        );
      }),
    );
  }
});
